window.__votdWeek && window.__votdWeek({"week":"2029-01-15","reading":"Joseph Smith—History 1:1–26","days":[{"d":"2029-01-15","ref":"Joseph Smith—History 1:2","b":"JS—History","c":1,"v":2,"he":"בְּהִיסְטוֹרְיָה זוֹ אֶכְתֹּב אֶת־הַמְּאֹרָעוֹת הַשּׁוֹנִים בְּיַחַס לַקְּהִילָּה הַזֹּאת בֶּאֱמֶת וּבְצֶדֶק כְּפִי שֶׁאֵרְעוּ וּכְפִי שֶׁהֵם עַתָּה קַיָּמִים וְעַתָּה 1838 הַשָּׁנָה הַשְּׁמִינִית מֵאָז הִתְיַסְּדָה הַקְּהִילָּה׃","en":"In this history I shall present the various events in relation to this Church, in truth and righteousness, as they have transpired, or as they at present exist, being now [1838] the eighth year since the organization of the said Church."},{"d":"2029-01-16","ref":"Joseph Smith—History 1:4","b":"JS—History","c":1,"v":4,"he":"מִשְׁפַּחְתּוֹ מָנְתָה אַחַת עֶשְׂרֵה נְפָשׁוֹת וְהֵם אָבִי יוֹסֵף סְמִית אִמִּי לוּסִי סְמִית אֲשֶׁר שְׁמָהּ לִפְנֵי נִשּׂוּאֶיהָ הָיָה מַק בַּת שְׁלֹמֹה מַק אַחַי אַלְוִין שֶׁמֵּת בַּתִּשְׁעָה עָשָׂר לְנוֹבֶמְבֶּר 1823 בִּשְׁנָתוֹ הָעֶשְׂרִים וְשֵׁשׁ חִירָם אֲנִי שְׁמוּאֵל הָרִיסוֹן וִילְיָם דּוֹן קַרְלוֹס וַאֲחָיוֹתַי סוֹפְרוֹנְיָה קָתְרִין וְלוּסִי׃","en":"His family consisting of eleven souls, namely, my father, Joseph Smith; my mother, Lucy Smith (whose name, previous to her marriage, was Mack, daughter of Solomon Mack); my brothers, Alvin (who died November 19th, 1823, in the 26th year of his age), Hyrum, myself, Samuel Harrison, William, Don Carlos; and my sisters, Sophronia, Catherine, and Lucy."},{"d":"2029-01-17","ref":"Joseph Smith—History 1:11","b":"JS—History","c":1,"v":11,"he":"בְּעָמְלִי תַּחַת הַקֹּשִׁי הַגָּדוֹל הַזֶּה שֶׁנִּגְרַם מִמַּחֲלֹקֶת כִּתּוֹת הַדָּת הָאֵלֶּה יוֹם אֶחָד קָרָאתִי בְּאִגֶּרֶת יַעֲקֹב פֶּרֶק א וּפָסוּק ה הָאוֹמֵר אִם אֶחָד מִכֶּם חָסֵר חׇכְמָה יִשְׁאַל מֵאֵת הָאֱלֹהִים הַנּוֹתֵן לְכֹל בְּנָדִיבוּת וְלֹא יְגָעֵר וְיִנָּתֵן לוֹ׃","en":"While I was laboring under the extreme difficulties caused by the contests of these parties of religionists, I was one day reading the Epistle of James, first chapter and fifth verse, which reads: If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him."},{"d":"2029-01-18","ref":"Joseph Smith—History 1:17","b":"JS—History","c":1,"v":17,"he":"אַךְ הוֹפִיעַ וּכְבָר מָצָאתִי אֶת־עַצְמִי מֻצָּל מִן הָאוֹיֵב שֶׁאָסַר אוֹתִי וְהָאוֹר נָח עָלַי רָאִיתִי שְׁנֵי אֲנָשִׁים זָהֳרָם וּכְבוֹדָם אֵין לְתָאֵר עוֹמְדִים מֵעָלַי בָּאֲוִיר אֶחָד מֵהֶם דִּבֶּר אֵלַי קוֹרֵא בִּשְׁמִי וְאָמַר בְּהַצְבִּיעוֹ אֶל הַשֵּׁנִי זֶה בְּנִי אֲהוּבִי שְׁמַע לוֹ׃","en":"It no sooner appeared than I found myself delivered from the enemy which held me bound. When the light rested upon me I saw two Personages, whose brightness and glory defy all description, standing above me in the air. One of them spake unto me, calling me by name and said, pointing to the other—This is My Beloved Son. Hear Him!"},{"d":"2029-01-19","ref":"Joseph Smith—History 1:18","b":"JS—History","c":1,"v":18,"he":"מַטָּרָתִי בָּלֶכֶת לִשְׁאֹל מֵאֵת יְהוָה הָיְתָה לָדַעַת אֵיזוֹ מִכׇּל הַכִּתּוֹת צוֹדֶקֶת כְּדֵי שֶׁאֵדַע לְאֵיזוֹ לְהִצְטָרֵף אַךְ לָכֵן שָׁלַטְתִּי עַל עַצְמִי עַד שֶׁיָּכֹלְתִּי לְדַבֵּר שָׁאַלְתִּי אֶת־הָאֲנָשִׁים הָעוֹמְדִים מֵעָלַי בָּאוֹר אֵיזוֹ מִכׇּל הַכִּתּוֹת צוֹדֶקֶת כִּי בָּעֵת הַזֹּאת לֹא עָלָה עַל לִבִּי שֶׁכֻּלָּן טוֹעוֹת וּלְאֵיזוֹ לְהִצְטָרֵף׃","en":"My object in going to inquire of the Lord was to know which of all the sects was right, that I might know which to join. No sooner, therefore, did I get possession of myself, so as to be able to speak, than I asked the Personages who stood above me in the light, which of all the sects was right (for at this time it had never entered into my heart that all were wrong)—and which I should join."},{"d":"2029-01-20","ref":"Joseph Smith—History 1:19","b":"JS—History","c":1,"v":19,"he":"נַעֲנֵיתִי שֶׁעָלַי שֶׁלֹּא לְהִצְטָרֵף לְאַחַת מֵהֶן כִּי כֻּלָּן טוֹעוֹת וְהָאִישׁ שֶׁדִּבֶּר אֵלַי אָמַר שֶׁכׇּל אֱמוּנוֹתֵיהֶן תּוֹעֵבָה בְּעֵינָיו שֶׁאוֹתָם הַמַּאֲמִינִים כֻּלָּם מֻשְׁחָתִים נִגָּשִׁים אֵלַי בְּשִׂפְתוֹתֵיהֶם אֲבָל לִבָּם רָחוֹק מִמֶּנִּי מְלַמְּדִים תּוֹרוֹת שֶׁהֵן מִצְווֹת אֲנָשִׁים וְיֵשׁ לָהֶם צוּרַת יִרְאַת אֱלֹהִים אֲבָל כֹּחָהּ הֵם מַכְחִישִׁים׃","en":"I was answered that I must join none of them, for they were all wrong; and the Personage who addressed me said that all their creeds were an abomination in his sight; that those professors were all corrupt; that: \"they draw near to me with their lips, but their hearts are far from me, they teach for doctrines the commandments of men, having a form of godliness, but they deny the power thereof.\""},{"d":"2029-01-21","ref":"Joseph Smith—History 1:26","b":"JS—History","c":1,"v":26,"he":"הִשְׂבַּעְתִּי עַתָּה אֶת־דַּעְתִּי בְּנוֹגֵעַ לָעוֹלָם הַכִּתָּתִי שֶׁלֹּא חוֹבָתִי לְהִצְטָרֵף לְאַחַת מֵהֶן אֶלָּא לְהִשָּׁאֵר כַּאֲשֶׁר הָיִיתִי עַד הוֹרָאָה נוֹסֶפֶת מָצָאתִי אֶת־עֵדוּת יַעֲקֹב אֲמִתִּית שֶׁאָדָם הַחָסֵר חׇכְמָה יָכוֹל לִשְׁאֹל מֵאֵת הָאֱלֹהִים וּלְקַבֵּל וְלֹא יִנָּזֵף׃","en":"I had now got my mind satisfied so far as the sectarian world was concerned—that it was not my duty to join with any of them, but to continue as I was until further directed. I had found the testimony of James to be true—that a man who lacked wisdom might ask of God, and obtain, and not be upbraided."}]});
